package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class OriginRegressionChecks {
    static int checks;static void check(boolean condition){checks++;if(!condition)throw new AssertionError("Origin regression check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid origin regression accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Random random=new Random(7738);double[][] x=new double[120][2];double[] y=new double[120];for(int i=0;i<y.length;i++){x[i][0]=2*random.nextDouble()-1;x[i][1]=1+random.nextGaussian();y[i]=.7*x[i][0]-1.2*x[i][1]+(.2+Math.abs(x[i][0]))*random.nextGaussian();}JsonArray cases=new JsonArray();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();
        for(int variant=0;variant<2;variant++)for(var covariance:RobustRegression.Covariance.values()){double[][] design=Matrices.copy(x);if(variant==1)for(var row:design){row[0]*=1e6;row[1]*=.001;}var fit=OriginRegression.fit(design,y,covariance,.95);check(fit.residualDegreesOfFreedom()==118&&fit.coefficients().length==2);check(Math.abs(fit.predict(design[0])-fit.fitted()[0])<1e-12);check(fit.uncenteredRSquared()>.6);double leverage=Arrays.stream(fit.leverage()).sum();check(Math.abs(leverage-2)<1e-12);var item=new JsonObject();item.add("predictors",gson.toJsonTree(design));item.add("response",gson.toJsonTree(y));item.add("fit",gson.toJsonTree(fit));if(variant==0&&(covariance==RobustRegression.Covariance.CLASSICAL||covariance==RobustRegression.Covariance.HC3)){var options=new Bootstrap.Options(40,431,.95,covariance==RobustRegression.Covariance.HC3?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var boot=OriginRegression.bootstrap(design,y,covariance,.95,options,null);check(boot.inference().successful()==40&&boot.inference().estimates().size()==2);item.add("bootstrapOptions",gson.toJsonTree(options));item.add("bootstrap",gson.toJsonTree(boot.inference()));}cases.add(item);}
        var zero=OriginRegression.fit(x,new double[y.length],RobustRegression.Covariance.CLASSICAL,.95);check(Double.isNaN(zero.uncenteredRSquared())&&Double.isNaN(zero.modelPValue()));check(zero.coefficients()[0]==0&&Double.isNaN(zero.terms().getFirst().pValue()));reject(()->OriginRegression.fit(new double[][]{{1,1},{2,2},{3,3}},new double[]{1,2,3},RobustRegression.Covariance.CLASSICAL,.95));reject(()->OriginRegression.fit(new double[][]{{1},{0},{0}},new double[]{1,2,3},RobustRegression.Covariance.HC3,.95));reject(()->OriginRegression.fit(x,y,RobustRegression.Covariance.CLASSICAL,1));Thread.currentThread().interrupt();try{OriginRegression.fit(x,y,RobustRegression.Covariance.CLASSICAL,.95);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Path output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
